namespace astradev_core {

namespace detail {

// Process-wide "has a Core ever been constructed" latch; a function-local
// static so every translation unit shares one instance.
inline std::atomic<bool>& StartedFlag() {
  static std::atomic<bool> started{false};
  return started;
}

// Unrecoverable: abort immediately instead of running teardown that might
// touch a half-dead backend.
[[noreturn]] inline void Fatal(const char* why) {
  std::fprintf(stderr, "astradev_core: fatal: %s\n", why);
  std::abort();
}

}  // namespace detail

/** @brief Manages process-wide services and subsystem lifetimes. */
class Core {
 public:
  /** @brief Constructs a stopped SDK runtime. */
  Core();

  /** @brief Stops all SDK services when the runtime is destroyed. */
  ~Core() noexcept;

  Core(const Core&) = delete;
  Core& operator=(const Core&) = delete;
  Core(Core&&) = delete;
  Core& operator=(Core&&) = delete;

  /** @brief Returns the sample library greeting. */
  std::string HelloWorld() const;

  /**
   * @brief Initializes Embosa and starts SDK subsystems.
   * @return True when all required services are running.
   * @note Subsystems start in the order sensor, control, system management.
   */
  bool Init();

  /** @brief Returns whether Embosa and all required subsystems are running. */
  bool IsRunning() const noexcept;

  /**
   * @brief Stops subsystems before releasing process-wide services.
   * @note Subsystems stop in the reverse of their start order: system
   * management, control, sensor.
   */
  void Close() noexcept;

  // Returns the WBC subsystem owned by this Core instance.
  Control& GetControl() noexcept;
  const Control& GetControl() const noexcept;

  /** @brief Returns the sensor subsystem owned by this Core instance. */
  Sensor& GetSensor() noexcept;

  /** @brief Returns the read-only sensor subsystem. */
  const Sensor& GetSensor() const noexcept;

  /** @brief Returns the system management subsystem owned by this Core. */
  system_mng::SystemMng& GetSystemMng() noexcept;

  /** @brief Returns the read-only system management subsystem. */
  const system_mng::SystemMng& GetSystemMng() const noexcept;

 private:
  // Enforces the process-wide construction and destruction constraints.
  class Guard {
   public:
    Guard() {
      if (detail::StartedFlag().exchange(true)) {
        detail::Fatal("Core can only be constructed once per process");
      }
      owner_thread_ = std::this_thread::get_id();
    }

    ~Guard() { assert(std::this_thread::get_id() == owner_thread_); }

   private:
    // Thread that constructed the Guard, asserted in the destructor.
    std::thread::id owner_thread_;
  };

  Guard guard_;
  Control control_;
  Sensor sensor_;
  system_mng::SystemMng system_mng_;
};

inline std::string Core::HelloWorld() const {
#ifdef NDEBUG
  return "Hello World!";
#else
  return "Hello World! DEBUG!";
#endif
}

// Exercises the third-party libraries; defined in src/3rdparty.cpp.
int ProbeThirdParty();

// Exercises the sensor_proto dependency; defined in src/3rdparty.cpp.
int ProbeSensorProto();

}  // namespace astradev_core

