namespace astradev_core {

/**
 * @brief Provides whole-body joint control through the WBC service.
 *
 * Applications normally obtain this object from Core::GetControl(), which
 * stays valid as long as the Core does.
 */
class Control final {
 public:
  Control(const Control&) = delete;
  Control& operator=(const Control&) = delete;
  Control(Control&&) = delete;
  Control& operator=(Control&&) = delete;

  /**
   * @brief Sends absolute joint position targets to the WBC service.
   *
   * Joints are selected by joint_names when it is not empty, otherwise by
   * joint_groups. Body groups share one motion duration, the largest joint
   * displacement divided by speed_rad_s, so the joint that travels farthest
   * moves at speed_rad_s. End-effector groups are commanded immediately.
   *
   * @param joint_positions Target positions, ordered as joint_names or as the
   * concatenated joints of joint_groups.
   * @param joint_groups Joint groups to control, such as "left_arm".
   * @param joint_names Joint names to control; takes precedence over
   * joint_groups.
   * @param speed_rad_s Maximum joint speed in rad/s; must be positive.
   * @return Result whose status is Status::kSuccess when the service accepts
   * the target, Status::kInvalidInput for bad arguments,
   * Status::kDataFetchFailed when a joint has no measured state, or another
   * error status.
   * @note The call returns once the service accepts the target and does not
   * wait for the joints to arrive.
   */
  data::Result<void> MoveJointsTo(
      const std::vector<double>& joint_positions,
      const std::vector<std::string>& joint_groups = {},
      const std::vector<std::string>& joint_names = {},
      double speed_rad_s = 0.2);

 private:
  friend class Core;

  /** @brief Constructs a stopped subsystem owned exclusively by Core. */
  Control();

  /** @brief Releases the subsystem owned exclusively by Core. */
  ~Control();

  /**
   * @brief Forward-declared private lifecycle bridge; defined in
   * implementation headers.
   */
  class Lifecycle;

  /** @brief Opaque library-owned WBC implementation. */
  class Impl;

  std::unique_ptr<Impl> impl_;
};

}  // namespace astradev_core

