#pragma once

#include <cstdint>

namespace astradev_core::data {

/**
 * @brief Status codes returned by SDK operations.
 *
 * Enumerators follow the SDK-wide `kCamelCase` naming convention.
 */
enum class Status : std::uint8_t {
  /** @brief The operation completed successfully. */
  kSuccess,

  /** @brief The operation exceeded its allowed wait duration. */
  kTimeout,

  /** @brief An unspecified runtime failure occurred. */
  kFault,

  /** @brief A caller-provided argument is invalid. */
  kInvalidInput,

  /** @brief A required runtime resource could not be initialized. */
  kInitFailed,

  /** @brief The requested operation conflicts with a transition in progress. */
  kInProgress,

  /** @brief The requested data became unreachable because a stream stopped. */
  kStoppedUnreached,

  /** @brief The source could not provide sensor data. */
  kDataFetchFailed,

  /** @brief Publishing sensor data failed. */
  kPublishFail,

  /** @brief Communication with the sensor service is disconnected. */
  kCommDisconnected,

  /** @brief No sensor matches the requested stable sensor identifier. */
  kSensorNotFound,

  /** @brief The sensor does not provide the requested public data type. */
  kDataTypeNotSupported,

  /** @brief No retained cache sample satisfies the requested lookup. */
  kCacheMiss,

  /** @brief Sentinel value equal to the number of status codes. */
  kStatusNum,
};

/**
 * @brief Returns the symbolic name of an SDK status code.
 * @param status Status code to convert.
 * @return Static null-terminated status name.
 */
inline const char* ToString(Status status) noexcept {
  switch (status) {
    case Status::kSuccess:
      return "SUCCESS";
    case Status::kTimeout:
      return "TIMEOUT";
    case Status::kFault:
      return "FAULT";
    case Status::kInvalidInput:
      return "INVALID_INPUT";
    case Status::kInitFailed:
      return "INIT_FAILED";
    case Status::kInProgress:
      return "IN_PROGRESS";
    case Status::kStoppedUnreached:
      return "STOPPED_UNREACHED";
    case Status::kDataFetchFailed:
      return "DATA_FETCH_FAILED";
    case Status::kPublishFail:
      return "PUBLISH_FAIL";
    case Status::kCommDisconnected:
      return "COMM_DISCONNECTED";
    case Status::kSensorNotFound:
      return "SENSOR_NOT_FOUND";
    case Status::kDataTypeNotSupported:
      return "DATA_TYPE_NOT_SUPPORTED";
    case Status::kCacheMiss:
      return "CACHE_MISS";
    case Status::kStatusNum:
      return "STATUS_NUM";
  }
  return "UNKNOWN";
}

}  // namespace astradev_core::data
