#pragma once

#include <chrono>
#include <cmath>
#include <cstdint>
#include <limits>
#include <stdexcept>

namespace astradev_core::data {

/** @brief Wall-clock timestamp compatible with robot message headers. */
class Timestamp final {
 public:
  /** @brief Number of nanoseconds in one second. */
  static constexpr std::uint32_t kNanosecondsPerSecond = 1'000'000'000U;

  /** @brief Constructs the Unix epoch timestamp. */
  constexpr Timestamp() noexcept = default;

  /**
   * @brief Constructs a timestamp from normalized components.
   * @param sec Whole seconds since the Unix epoch.
   * @param nanosec Nanosecond offset in the current second.
   */
  constexpr Timestamp(std::int32_t sec, std::uint32_t nanosec) noexcept
      : sec_(sec), nanosec_(nanosec) {}

  /** @brief Returns the current system-clock time. */
  [[nodiscard]] static Timestamp Now() {
    const auto elapsed = std::chrono::duration_cast<std::chrono::nanoseconds>(
        std::chrono::system_clock::now().time_since_epoch());
    auto seconds = std::chrono::duration_cast<std::chrono::seconds>(elapsed);
    auto nanoseconds = elapsed - seconds;
    if (nanoseconds.count() < 0) {
      seconds -= std::chrono::seconds{1};
      nanoseconds += std::chrono::seconds{1};
    }

    const auto seconds_count = seconds.count();
    if (seconds_count < std::numeric_limits<std::int32_t>::min() ||
        seconds_count > std::numeric_limits<std::int32_t>::max()) {
      throw std::out_of_range("Current time exceeds Timestamp range");
    }

    return Timestamp{static_cast<std::int32_t>(seconds_count),
                     static_cast<std::uint32_t>(nanoseconds.count())};
  }

  /**
   * @brief Converts floating-point Unix seconds to a normalized timestamp.
   * @param seconds Seconds since the Unix epoch.
   * @return Normalized timestamp.
   * @throws std::invalid_argument if seconds is not finite.
   * @throws std::out_of_range if seconds exceeds the supported range.
   */
  [[nodiscard]] static Timestamp FromSeconds(double seconds) {
    if (!std::isfinite(seconds)) {
      throw std::invalid_argument("Timestamp seconds must be finite");
    }

    double integral_seconds = 0.0;
    double fractional_seconds = std::modf(seconds, &integral_seconds);
    if (fractional_seconds < 0.0) {
      fractional_seconds += 1.0;
      integral_seconds -= 1.0;
    }

    const double minimum_sec =
        static_cast<double>(std::numeric_limits<std::int32_t>::min());
    const double maximum_sec =
        static_cast<double>(std::numeric_limits<std::int32_t>::max());
    if (integral_seconds < minimum_sec || integral_seconds > maximum_sec) {
      throw std::out_of_range("Timestamp seconds exceed int32 range");
    }

    std::int64_t sec = static_cast<std::int64_t>(integral_seconds);
    std::uint64_t nanosec = static_cast<std::uint64_t>(
        std::llround(fractional_seconds * kNanosecondsPerSecond));

    if (nanosec >= kNanosecondsPerSecond) {
      ++sec;
      nanosec = 0;
    }
    if (sec < std::numeric_limits<std::int32_t>::min() ||
        sec > std::numeric_limits<std::int32_t>::max()) {
      throw std::out_of_range("Timestamp seconds exceed int32 range");
    }

    return {static_cast<std::int32_t>(sec),
            static_cast<std::uint32_t>(nanosec)};
  }

  /**
   * @brief Converts signed Unix nanoseconds to a normalized timestamp.
   * @param nanoseconds Nanoseconds since the Unix epoch.
   * @return Normalized timestamp.
   * @throws std::out_of_range if the seconds component exceeds int32 range.
   */
  [[nodiscard]] static Timestamp FromNanoseconds(std::int64_t nanoseconds) {
    std::int64_t sec = nanoseconds / kNanosecondsPerSecond;
    std::int64_t nanosec = nanoseconds % kNanosecondsPerSecond;
    if (nanosec < 0) {
      --sec;
      nanosec += kNanosecondsPerSecond;
    }
    if (sec < std::numeric_limits<std::int32_t>::min() ||
        sec > std::numeric_limits<std::int32_t>::max()) {
      throw std::out_of_range("Timestamp nanoseconds exceed int32 range");
    }
    return Timestamp{static_cast<std::int32_t>(sec),
                     static_cast<std::uint32_t>(nanosec)};
  }

  /** @brief Returns a mutable reference to the seconds component. */
  [[nodiscard]] constexpr std::int32_t& Sec() noexcept { return sec_; }

  /** @brief Returns the seconds component. */
  [[nodiscard]] constexpr std::int32_t Sec() const noexcept { return sec_; }

  /** @brief Returns a mutable reference to the nanoseconds component. */
  [[nodiscard]] constexpr std::uint32_t& Nanosec() noexcept { return nanosec_; }

  /** @brief Returns the nanoseconds component. */
  [[nodiscard]] constexpr std::uint32_t Nanosec() const noexcept {
    return nanosec_;
  }

  /** @brief Returns whether the nanoseconds component is normalized. */
  [[nodiscard]] constexpr bool IsValid() const noexcept {
    return nanosec_ < kNanosecondsPerSecond;
  }

  /** @brief Converts this timestamp to floating-point Unix seconds. */
  [[nodiscard]] constexpr double ToSeconds() const noexcept {
    return static_cast<double>(sec_) +
           static_cast<double>(nanosec_) /
               static_cast<double>(kNanosecondsPerSecond);
  }

  /** @brief Converts this timestamp to signed Unix nanoseconds. */
  [[nodiscard]] constexpr std::int64_t ToNanoseconds() const noexcept {
    return static_cast<std::int64_t>(sec_) * kNanosecondsPerSecond + nanosec_;
  }

 private:
  std::int32_t sec_{0};
  std::uint32_t nanosec_{0};
};

}  // namespace astradev_core::data
