/**
 * @brief Whole-robot system management facade.
 *
 * Core constructs and owns this object; its lifetime matches the Core's, and
 * it is neither copyable nor movable.
 */
class SystemMng final {
 public:
  SystemMng(const SystemMng&) = delete;
  SystemMng& operator=(const SystemMng&) = delete;
  SystemMng(SystemMng&&) = delete;
  SystemMng& operator=(SystemMng&&) = delete;

  // -- battery state -------------------------------------------------------

  /**
   * @brief Returns the latest battery/BMS information.
   * @return The battery information, or an error result.
   */
  [[nodiscard]] data::Result<BatteryInfo> GetBatteryState() const;

  // -- component services --------------------------------------------------

  /**
   * @brief Returns the component services and their run states.
   * @return One entry per service, each with its own observation time and a
   * reason when the state is unknown, or an error result.
   */
  [[nodiscard]] data::Result<ComponentServiceStatesSnapshot>
  GetComponentServiceStates() const;

  /**
   * @brief Starts the targeted component service(s).
   * @param request Manage request naming the operation, the granularity, and
   * the target service.
   * @param timeout Maximum time to wait for admission.
   * @return A handle to the accepted operation, or an error result.
   * @note Admission is not completion.
   */
  [[nodiscard]] data::Result<OperationHandle> StartComponentServices(
      const ComponentServiceManageRequest& request,
      std::chrono::milliseconds timeout = kDefaultTimeout);

  /**
   * @brief Stops the targeted component service(s).
   * @param request Manage request naming the operation, the granularity, and
   * the target service.
   * @param timeout Maximum time to wait for admission.
   * @return A handle to the accepted operation, or an error result.
   * @note Admission is not completion.
   */
  [[nodiscard]] data::Result<OperationHandle> StopComponentServices(
      const ComponentServiceManageRequest& request,
      std::chrono::milliseconds timeout = kDefaultTimeout);

  /**
   * @brief Restarts the targeted component service(s).
   * @param request Manage request naming the operation, the granularity, and
   * the target service.
   * @param timeout Maximum time to wait for admission.
   * @return A handle to the accepted operation, or an error result.
   * @note The configuration read at launch is reloaded; admission is not
   * completion.
   */
  [[nodiscard]] data::Result<OperationHandle> RestartComponentServices(
      const ComponentServiceManageRequest& request,
      std::chrono::milliseconds timeout = kDefaultTimeout);

  // -- compute and network -------------------------------------------------

  /**
   * @brief Returns the whole-robot resource view (HPU + XCU + disks).
   * @return The resource status, or an error result.
   * @note A disk without a source reports its used/total as absent (unknown).
   */
  [[nodiscard]] data::Result<SystemResourceInfo> GetSystemResourceStatus()
      const;

  /**
   * @brief Returns the network information of the target robot.
   * @return The network information, or an error result.
   */
  [[nodiscard]] data::Result<NetworkInterfaceInfo> GetNetworkStatus() const;

  // -- preset poses --------------------------------------------------------

  /**
   * @brief Returns the available preset poses.
   * @return The preset poses, or an error result.
   * @note The poses are loaded once during Init.
   */
  [[nodiscard]] data::Result<PresetPoseList> GetAvailablePresetPoses() const;

  // -- runtime run state ---------------------------------------------------

  /**
   * @brief Returns the whole-robot run conclusion.
   * @return The per-domain states (D0..D4) and the blocking reasons behind
   * them, or an error result.
   */
  [[nodiscard]] data::Result<RunStateSnapshot> GetRobotRunState() const;

  // -- Shared: operation observation ---------------------------------------

  /**
   * @brief Re-observes an accepted operation by id.
   * @param operation_id Identifier of the operation to re-observe.
   * @param timeout Maximum time to wait for the lookup.
   * @return A handle to the operation, or an error result.
   * @note An unknown or expired id returns data::Status::kFault and starts no
   * new side effect.
   */
  [[nodiscard]] data::Result<OperationHandle> GetOperation(
      const std::string& operation_id,
      std::chrono::milliseconds timeout = kDefaultTimeout) const;

 private:
  friend class astradev_core::Core;

  /** @brief Constructs a stopped subsystem owned exclusively by Core. */
  SystemMng();

  /** @brief Releases the subsystem owned exclusively by Core. */
  ~SystemMng();

  /** @brief Forward-declared private lifecycle bridge for Core. */
  class Lifecycle;

  /** @brief Opaque library-owned module implementation. */
  class Impl;

  std::unique_ptr<Impl> impl_;
};

}  // namespace astradev_core::system_mng
