/**
 * @brief Pixel formats supported by RgbImage and its conversion helpers.
 *
 * Sensor acquisition produces BGRA. Applications can explicitly convert that
 * image to another format with the functions declared in rgb_conversion.hpp.
 */
enum class RgbOutputFormat : std::uint8_t {
  /** @brief Blue, green, red, and alpha channels in byte order. */
  kBgra,
  /** @brief Red, green, and blue channels in byte order. */
  kRgb,
  /** @brief Blue, green, and red channels in byte order. */
  kBgr,
  /** @brief Red, green, blue, and alpha channels in byte order. */
  kRgba,
  /** @brief JPEG-compressed image bytes. */
  kJpeg,
};

/**
 * @brief CPU-owned color image returned by the sensor API.
 *
 * Images acquired from a sensor use BGRA8. The data vector owns its storage,
 * so an image remains valid after its callback returns or its source stream is
 * closed. Conversion helpers create another independently owned RgbImage.
 */
struct RgbImage {
  /** @brief Acquisition metadata supplied by the sensor source. */
  data::Header header;

  /** @brief Pixel encoding name, such as `bgra8`, `rgb8`, or `jpeg`. */
  std::string format{"bgra8"};

  /** @brief Pixel format represented by data. */
  RgbOutputFormat output_format{RgbOutputFormat::kBgra};

  /** @brief Image width in pixels. */
  std::uint32_t width{0};

  /** @brief Image height in pixels. */
  std::uint32_t height{0};

  /** @brief Number of valid image planes described by the layout arrays. */
  std::uint32_t plane_count{0};

  /** @brief Byte stride for each plane; unused entries are zero. */
  std::array<std::uint32_t, 2> stride_bytes{};

  /** @brief Byte offset of each plane within data; unused entries are zero. */
  std::array<std::uint32_t, 2> plane_offset_bytes{};

  /** @brief CPU-owned pixel or encoded-image bytes. */
  std::vector<std::uint8_t> data;
};

}  // namespace astradev_core::data::sensor

