Core::Core() { internal::EnsureEmbosaRuntime(); }

Core::~Core() noexcept { Close(); }

bool Core::Init() {
  const bool initialized = internal::InitializeEmbosaRuntime(
      [this] {
        system_mng::SystemMng::Lifecycle::Shutdown(system_mng_);
        Control::Lifecycle::Shutdown(control_);
        Sensor::Lifecycle::Shutdown(sensor_);
      },
      [this] {
        return !system_mng::SystemMng::Lifecycle::IsStarted(system_mng_) &&
               !Control::Lifecycle::IsStarted(control_) &&
               !Sensor::Lifecycle::IsStarted(sensor_);
      });
  if (!initialized) {
    return false;
  }

  if (!Sensor::Lifecycle::Start(sensor_) ||
      !Control::Lifecycle::Start(control_) ||
      !system_mng::SystemMng::Lifecycle::Start(system_mng_)) {
    Close();
    return false;
  }
  return true;
}

bool Core::IsRunning() const noexcept {
  return internal::IsEmbosaRuntimeRunning() &&
         Sensor::Lifecycle::IsStarted(sensor_) &&
         Control::Lifecycle::IsStarted(control_) &&
         system_mng::SystemMng::Lifecycle::IsStarted(system_mng_);
}

void Core::Close() noexcept {
  system_mng::SystemMng::Lifecycle::Shutdown(system_mng_);
  Control::Lifecycle::Shutdown(control_);
  Sensor::Lifecycle::Shutdown(sensor_);
  internal::ShutdownEmbosaRuntime();
}

