/** @brief 控制一个"有容量上限的传感器缓存"的配置项。 */
struct CacheOptions {
  /** @brief 这个缓存最多保留多少个采样点。 */
  std::size_t capacity{100};

  /** @brief 一个采样点最多保留多长时间，超过就丢掉。 */
  std::chrono::milliseconds max_age{5000};
};

/** @brief 查询缓存时的条件：时间戳区间 + 最多返回多少条。 */
struct CacheQuery {
  /** @brief 时间戳下界（包含），单位纳秒。 */
  std::int64_t begin_timestamp_ns{0};

  /** @brief 时间戳上界（不包含），单位纳秒。 */
  std::int64_t end_timestamp_ns{0};

  /** @brief 这次查询最多返回多少个采样点。 */
  std::size_t limit{100};
};

/**
 * @brief 用来查询某个"有容量上限的传感器缓存"的句柄，析构时自动释放。
 * @tparam T 这个缓存所保留的传感器数据类型（公开数据类型）。
 */
template <typename T>
class SensorCache {
 public:
  // 缓存里存的是 shared_ptr<const T>：多个使用方共享同一份数据，且数据不可被修改。
  using DataPtr = std::shared_ptr<const T>;

  /** @brief 构造一个"未激活"的缓存句柄。 */
  SensorCache() = default;

  // 禁止拷贝：句柄是独占的。
  SensorCache(const SensorCache&) = delete;
  SensorCache& operator=(const SensorCache&) = delete;

  /** @brief 转移另一个缓存句柄的所有权。 */
  SensorCache(SensorCache&& other) noexcept;

  /** @brief 用另一个缓存句柄替换掉当前句柄。 */
  SensorCache& operator=(SensorCache&& other) noexcept;

  /** @brief 句柄销毁时关闭缓存。 */
  ~SensorCache();

  /**
   * @brief 查询某个时间戳区间内保留下来的采样点。
   * @param query 半开时间戳区间（左闭右开），以及最多返回多少条。
   * @return 按采集时间排序的采样点列表，或者一个错误结果。
   */
  data::Result<std::vector<DataPtr>> Query(const CacheQuery& query) const;

  /**
   * @brief 返回最新的若干个采样点。
   * @param count 最多返回多少个采样点。
   * @return 按采集时间排序的采样点列表，或者一个错误结果。
   */
  data::Result<std::vector<DataPtr>> Latest(std::size_t count) const;

  /**
   * @brief 返回与给定源时间戳最接近的那个保留采样点。
   * @param timestamp 用来查找的源时间戳。
   * @return 最近的那个采样点；缓存为空时返回 kCacheMiss。
   * @note 两个候选一样近时，取"源时间戳更早"的那个。
   *       如果有多个采样点的源时间戳相同，则取"最近收到"的那个。
   */
  data::Result<DataPtr> GetNearestByTimestamp(
      const data::Timestamp& timestamp) const;

  /** @brief 关闭这个缓存，但不影响它对应的数据流。 */
  void Close() noexcept;

  /**
   * @brief 返回这个缓存是否处于激活状态。
   * @return 只要还能接收并对外提供采样点，就是 true。
   */
  bool IsActive() const noexcept;

 private:
  /** @brief 由库自己实现的不透明传感器缓存实现类。 */
  class Impl;

  explicit SensorCache(std::shared_ptr<Impl> impl);

  std::shared_ptr<Impl> impl_;

  friend class Sensor;
};

/** @brief 控制"异步订阅投递方式"的配置项。 */
struct SubscribeOptions {
  /** @brief 队列里最多缓存多少帧，满了就丢掉最旧的那一帧。 */
  std::size_t queue_capacity{8};
};

/** @brief 一次异步传感器订阅的句柄，只能移动、不能拷贝，析构时自动释放。 */
class Subscription {
 public:
  /** @brief 构造一个"未激活"的订阅句柄。 */
  Subscription() = default;

  // 禁止拷贝：句柄是独占的。
  Subscription(const Subscription&) = delete;
  Subscription& operator=(const Subscription&) = delete;

  /** @brief 转移另一个订阅句柄的所有权。 */
  Subscription(Subscription&& other) noexcept;

  /** @brief 停掉当前订阅，并接管另一个订阅句柄。 */
  Subscription& operator=(Subscription&& other) noexcept;

  /** @brief 句柄销毁时停止回调投递。 */
  ~Subscription();

  /** @brief 停止后续的回调投递。 */
  void Stop() noexcept;

  /**
   * @brief 返回这个订阅当前是否激活。
   * @return 只要回调投递仍然开启，就是 true。
   */
  bool IsActive() const noexcept;

  /**
   * @brief 返回这个订阅丢掉了多少帧。
   * @return 因为回调队列满而被丢弃的帧数。
   */
  std::uint64_t DroppedFrames() const noexcept;

 private:
  /** @brief 由库自己实现的不透明订阅实现类。 */
  class Impl;

  explicit Subscription(std::shared_ptr<Impl> impl);

  std::shared_ptr<Impl> impl_;

  friend class Sensor;
};

/**
 * @brief 按需访问所有受支持的传感器数据流。
 *
 * 应用一般是通过 Core::GetSensor() 拿到这个对象。
 * "传感器标识 + 数据类型"这一对组合，共用同一条延迟创建的数据流。
 * 传感器标识可以从能力发现（capability discovery）里获取（前提是该功能可用）。
 */
class Sensor final {
 public:
  // 禁止拷贝、禁止移动：一个 Core 只对应一个 Sensor。
  Sensor(const Sensor&) = delete;
  Sensor& operator=(const Sensor&) = delete;
  Sensor(Sensor&&) = delete;
  Sensor& operator=(Sensor&&) = delete;

  /**
   * @brief 等这一调用开始之后到达的第一帧传感器数据。
   * @tparam T 必须是 EncodedVideoStream、RgbImage、DepthImage、PointCloud、Imu 之一。
   * @param sensor_id 稳定的传感器标识。
   * @param timeout 最多等多久。
   * @return 下一帧不可变的数据，或者一个错误结果。
   */
  template <typename T>
  data::Result<std::shared_ptr<const T>> ReadOnce(
      std::string_view sensor_id,
      std::chrono::milliseconds timeout = std::chrono::milliseconds(1000));

  /**
   * @brief 在 SDK 的投递线程上异步回调传感器数据。
   * @tparam T 必须是 EncodedVideoStream、RgbImage、DepthImage、PointCloud、Imu 之一。
   * @param sensor_id 稳定的传感器标识。
   * @param callback 每收到一帧就调用一次的函数。
   * @param options 回调队列的容量配置。
   * @return 一个只能移动的订阅句柄，或者一个错误结果。
   */
  template <typename T>
  data::Result<Subscription> Subscribe(
      std::string_view sensor_id,
      std::function<void(std::shared_ptr<const T>)> callback,
      SubscribeOptions options = {});

  /**
   * @brief 为某条传感器数据流创建一个独立的、有容量上限的缓存。
   * @tparam T 必须是 EncodedVideoStream、RgbImage、DepthImage、PointCloud、Imu 之一。
   * @param sensor_id 稳定的传感器标识。
   * @param options 缓存的容量与保留时长配置。
   * @return 一个只能移动的缓存句柄，或者一个错误结果。
   */
  template <typename T>
  data::Result<SensorCache<T>> CreateCache(std::string_view sensor_id,
                                           CacheOptions options = {});

 private:
  friend class Core;

  /** @brief 构造一个处于已停止状态的子系统，只能由 Core 独占拥有。 */
  Sensor();

  /** @brief 释放这个只能由 Core 独占拥有的子系统。 */
  ~Sensor();

  /** @brief 前置声明的私有生命周期桥接类；定义放在实现用的头文件里。 */
  class Lifecycle;

  /** @brief 由库自己实现的不透明传感器实现类。 */
  class Impl;

  std::unique_ptr<Impl> impl_;
};

}  // namespace astradev_core

