  Xxx(Xxx&&) = delete;
  Xxx& operator=(Xxx&&) = delete;

  // ↓↓↓ 这里写你的业务方法，比如
  data::Result<int> GetSomething() const;
  void SetSomething(int v);
  // ↑↑↑ 只有这一段是你真正要设计的

 private:
  friend class Core;                           // 骨架：必须写，否则 Core 调不到你
  Xxx();                                       // 骨架：私有构造
  ~Xxx();

  class Lifecycle;                             // 骨架：给 Core 用的开关桥
  class Impl;
  std::unique_ptr<Impl> impl_;
};
```

