/**
 * @file control.cpp
 * @brief Implements whole-body joint control on top of the WBC service.
 */

#include <galbot/singorix_proto/singorix_error.pb.h>
#include <galbot/singorix_proto/singorix_info.pb.h>
#include <galbot/singorix_proto/singorix_target.pb.h>

#include <algorithm>
#include <chrono>
#include <cmath>
#include <condition_variable>
#include <cstddef>
#include <cstdint>
#include <embosa/embosa.hpp>
#include <exception>
#include <map>
#include <memory>
#include <mutex>
#include <string>
#include <unordered_map>
#include <utility>
#include <vector>

#include "impl/control/control_lifecycle.hpp"
#include "impl/control/joint_table.hpp"

namespace astradev_core {
namespace {

namespace proto = galbot::singorix_proto;

using data::Result;
using data::Status;

using TargetClient = galbot::embosa::SerializationClient<proto::SingoriXTarget,
                                                         proto::SingoriXError>;
using WbcInfoReader = galbot::embosa::SerializationReader<proto::WBCInfo>;

constexpr char kNodeName[] = "astra_core_wbc_node";
constexpr char kTargetServer[] = "singorix/wbcs/target_server";
constexpr char kWbcInfoTopic[] = "singorix/wbcs/wbc_info";

constexpr std::chrono::seconds kRequestTimeout{10};
/** @brief Error codes at or above this level reject a target. */
constexpr std::int64_t kFatalErrorCode = 0x30000;

/** @brief Latest measured joint positions reported by the WBC service. */
struct JointStateCache {
  std::mutex mutex;
  std::condition_variable updated;
  std::unordered_map<std::string, double> positions;

  /** @brief Updates cached positions from a WBCInfo message. */
  void Update(const proto::WBCInfo& message) {
    const auto& info = message.joint_info();
    if (info.names_size() != info.state_pos_size()) {
      return;
    }
    {
      std::lock_guard<std::mutex> lock(mutex);
      for (int i = 0; i < info.names_size(); ++i) {
        positions[info.names(i)] = info.state_pos(i);
      }
    }
    updated.notify_all();
  }

  /** @brief Waits until at least one joint state has been received. */
  bool WaitForFirstState(std::chrono::seconds timeout) {
    std::unique_lock<std::mutex> lock(mutex);
    return updated.wait_for(lock, timeout,
                            [this] { return !positions.empty(); });
  }
};

/** @brief Target positions of one joint group, ordered as commanded. */
struct GroupTarget {
  std::vector<std::string> joint_names;
  std::vector<double> positions;
};

using GroupTargets = std::map<std::string, GroupTarget>;

/** @brief Expands the caller's selection into joint names; names win. */
Result<std::vector<std::string>> ResolveJointNames(
    const internal::JointTable& table,
    const std::vector<std::string>& joint_groups,
    const std::vector<std::string>& joint_names) {
  using NamesResult = Result<std::vector<std::string>>;
  if (!joint_names.empty()) {
    for (const auto& name : joint_names) {
      if (!table.IsActiveJoint(name)) {
        return NamesResult::Failure(
            Status::kInvalidInput,
            "joint is unknown or not controllable: " + name);
      }
    }
    return NamesResult::Success(joint_names);
  }

  std::vector<std::string> names;
  for (const auto& group_name : joint_groups) {
    const auto* group = table.FindGroup(group_name);
    if (group == nullptr || !group->is_active) {
      return NamesResult::Failure(
          Status::kInvalidInput,
          "joint group is unknown or not controllable: " + group_name);
    }
    names.insert(names.end(), group->joint_names.begin(),
                 group->joint_names.end());
  }
  if (names.empty()) {
    return NamesResult::Failure(
        Status::kInvalidInput,
        "either joint_groups or joint_names must be specified");
  }
  return NamesResult::Success(std::move(names));
}

/** @brief Splits validated joint targets by the group owning each joint. */
Result<GroupTargets> GroupJointPositions(
    const internal::JointTable& table,
    const std::vector<std::string>& joint_names,
    const std::vector<double>& joint_positions) {
  if (joint_names.size() != joint_positions.size()) {
    return Result<GroupTargets>::Failure(
        Status::kInvalidInput,
        "expected " + std::to_string(joint_names.size()) +
            " joint positions, got " + std::to_string(joint_positions.size()));
  }
  GroupTargets targets;
  for (std::size_t i = 0; i < joint_names.size(); ++i) {
    if (!std::isfinite(joint_positions[i])) {
      return Result<GroupTargets>::Failure(
          Status::kInvalidInput,
          "joint position is not finite: " + joint_names[i]);
    }
    auto& target = targets[*table.GroupOf(joint_names[i])];
    target.joint_names.push_back(joint_names[i]);
    target.positions.push_back(joint_positions[i]);
  }
  return Result<GroupTargets>::Success(std::move(targets));
}

/**
 * @brief Derives the motion duration from the largest joint displacement.
 *
 * Matches the legacy SDK: every joint shares one duration, so the joint that
 * travels farthest moves at speed_rad_s and the others move slower.
 */
Result<double> ComputeMoveTimeS(
    const std::unordered_map<std::string, double>& current_positions,
    const std::vector<std::string>& joint_names,
    const std::vector<double>& joint_positions, double speed_rad_s) {
  double max_diff = 0.0;
  for (std::size_t i = 0; i < joint_names.size(); ++i) {
    const auto it = current_positions.find(joint_names[i]);
    if (it == current_positions.end()) {
      return Result<double>::Failure(
          Status::kDataFetchFailed,
          "no measured state for joint: " + joint_names[i]);
    }
    max_diff = std::max(max_diff, std::abs(joint_positions[i] - it->second));
  }
  return Result<double>::Success(max_diff / speed_rad_s);
}

/** @brief Adds one joint group's position target to a WBC target message. */
void AddGroupTarget(const internal::JointGroupInfo& group,
                    const GroupTarget& target, double move_time_s,
                    proto::SingoriXTarget& message) {
  // End effectors jump to the target; body groups follow the duration.
  const double time_s = group.is_end_effector ? 0.0 : move_time_s;
  const auto time_sec = static_cast<std::int64_t>(time_s);
  auto& trajectory =
      (*message.mutable_target_group_trajectory_map())[group.name];
  auto* config = trajectory.mutable_target_config();
  config->set_target_data(proto::TargetData::TARGET_DATA_DEFAULT);
  config->set_target_type(group.is_end_effector
                              ? proto::TargetType::TARGET_TYPE_OVERRIDE
                              : proto::TargetType::TARGET_TYPE_PROVERRIDE);
  config->set_target_sampling(proto::TargetSampling::TARGET_SAMPLING_DEFAULT);
  config->set_target_priority(1);

  auto* command = trajectory.add_group_commands();
  command->mutable_time_from_start()->set_sec(time_sec);
  command->mutable_time_from_start()->set_nanosec(
      static_cast<std::uint32_t>((time_s - time_sec) * 1e9));
  for (std::size_t i = 0; i < target.joint_names.size(); ++i) {
    trajectory.add_joint_names(target.joint_names[i]);
    command->add_joint_commands()->set_position(target.positions[i]);
  }
}

const std::string* FindFaultedGroup(const proto::SingoriXError& error,
                                    const GroupTargets& targets) {
  for (const auto& item : targets) {
    const auto it = error.error_map().find(item.first + "_max_error_level");
    if (it != error.error_map().end() &&
        it->second.error_code() >= kFatalErrorCode) {
      return &item.first;
    }
  }
  return nullptr;
}

}  // namespace

/** @brief Owns the WBC Node, target client, and joint state reader. */
class Control::Impl final {
 public:
  Impl() = default;
  ~Impl() { Shutdown(); }

  Result<void> Start();

  Result<void> MoveJointsTo(const std::vector<double>& joint_positions,
                            const std::vector<std::string>& joint_groups,
                            const std::vector<std::string>& joint_names,
                            double speed_rad_s);

  bool IsStarted() const noexcept {
    std::lock_guard<std::mutex> lock(mutex_);
    return target_client_ != nullptr;
  }

  void Shutdown() noexcept {
    std::lock_guard<std::mutex> lock(mutex_);
    target_client_.reset();
    wbc_info_reader_.reset();
    joint_states_.reset();
    node_.reset();
  }

 private:
  const internal::JointTable table_{internal::JointTable::CreateG1()};
  mutable std::mutex mutex_;
  std::unique_ptr<galbot::embosa::Node> node_;
  std::shared_ptr<TargetClient> target_client_;
  std::shared_ptr<WbcInfoReader> wbc_info_reader_;
  std::shared_ptr<JointStateCache> joint_states_;
};

Result<void> Control::Impl::Start() {
  std::lock_guard<std::mutex> lock(mutex_);
  if (target_client_) {
    return Result<void>::Success();
  }
  try {
    auto node = galbot::embosa::CreateNode(kNodeName);
    if (!node) {
      return Result<void>::Failure(Status::kInitFailed,
                                   "failed to create the Astra Core WBC node");
    }
    // Subscribe first so joint state discovery overlaps the server wait.
    auto joint_states = std::make_shared<JointStateCache>();
    std::weak_ptr<JointStateCache> weak_states = joint_states;
    auto reader = node->CreateReader<proto::WBCInfo>(
        kWbcInfoTopic,
        [weak_states](const std::shared_ptr<proto::WBCInfo>& message,
                      const void*) {
          auto states = weak_states.lock();
          if (states && message) {
            states->Update(*message);
          }
        });
    if (!reader) {
      return Result<void>::Failure(Status::kInitFailed,
                                   "failed to create the WBC info reader");
    }
    galbot::embosa::RpcQos rpc_qos;
    rpc_qos.intra_core_rpc_qos.transport_type =
        galbot::embosa::IntraCoreTransportType::LARGE_DATA_TRANSPORT;
    auto client =
        node->CreateClient<proto::SingoriXTarget, proto::SingoriXError>(
            kTargetServer, rpc_qos);
    if (!client) {
      return Result<void>::Failure(Status::kInitFailed,
                                   "failed to create the WBC target client");
    }

    if (client->GetMatchedServerCount() == 0) {
      client->WaitForServerConnected(kRequestTimeout);
      if (client->GetMatchedServerCount() == 0) {
        return Result<void>::Failure(Status::kCommDisconnected,
                                     "WBC target server is not reachable");
      }
    }
    // Speed-based timing needs the current joint positions.
    if (!joint_states->WaitForFirstState(kRequestTimeout)) {
      return Result<void>::Failure(
          Status::kCommDisconnected,
          std::string("no joint state received on ") + kWbcInfoTopic);
    }
    node_ = std::move(node);
    joint_states_ = std::move(joint_states);
    wbc_info_reader_ = std::move(reader);
    target_client_ = std::move(client);
  } catch (const std::exception& exception) {
    return Result<void>::Failure(
        Status::kInitFailed,
        "failed to initialize WBC: " + std::string(exception.what()));
  } catch (...) {
    return Result<void>::Failure(Status::kInitFailed,
                                 "failed to initialize WBC");
  }
  return Result<void>::Success();
}

Result<void> Control::Impl::MoveJointsTo(
    const std::vector<double>& joint_positions,
    const std::vector<std::string>& joint_groups,
    const std::vector<std::string>& joint_names, double speed_rad_s) {
  if (!std::isfinite(speed_rad_s) || speed_rad_s <= 0.0) {
    return Result<void>::Failure(Status::kInvalidInput,
                                 "speed_rad_s must be finite and positive");
  }
  auto names = ResolveJointNames(table_, joint_groups, joint_names);
  if (!names) {
    return Result<void>::Failure(names.status, names.message);
  }
  auto targets = GroupJointPositions(table_, names.value, joint_positions);
  if (!targets) {
    return Result<void>::Failure(targets.status, targets.message);
  }

  std::shared_ptr<TargetClient> client;
  std::shared_ptr<JointStateCache> joint_states;
  {
    std::lock_guard<std::mutex> lock(mutex_);
    client = target_client_;
    joint_states = joint_states_;
  }
  if (!client || !joint_states) {
    return Result<void>::Failure(Status::kInitFailed,
                                 "WBC subsystem is not started");
  }

  std::unordered_map<std::string, double> current_positions;
  {
    std::lock_guard<std::mutex> lock(joint_states->mutex);
    current_positions = joint_states->positions;
  }
  const auto move_time_s = ComputeMoveTimeS(current_positions, names.value,
                                            joint_positions, speed_rad_s);
  if (!move_time_s) {
    return Result<void>::Failure(move_time_s.status, move_time_s.message);
  }

  proto::SingoriXTarget message;
  for (const auto& item : targets.value) {
    AddGroupTarget(*table_.FindGroup(item.first), item.second,
                   move_time_s.value, message);
  }

  const auto reply = client->SendRequest(message, kRequestTimeout);
  if (!reply) {
    return Result<void>::Failure(Status::kTimeout,
                                 "WBC target request received no reply");
  }
  if (const auto* group = FindFaultedGroup(*reply, targets.value)) {
    return Result<void>::Failure(
        Status::kFault,
        "WBC rejected the target with a fatal error: " + *group);
  }
  return Result<void>::Success();
}

